<?php require __DIR__.'/../app/bootstrap.php'; require __DIR__.'/../app/layout.php'; require_permission('manage_purchases');$id=(int)($_GET['batch_id']??0);$st=db()->prepare('SELECT b.*,p.sku,p.product_name,p.color,p.size,p.mrp,p.retail_price,p.serial_tracking FROM batches b JOIN products p ON p.id=b.product_id WHERE b.id=?');$st->execute([$id]);$b=$st->fetch();if(!$b)exit('Batch not found');
$isSerial=(int)$b['serial_tracking']===1;$serials=[];if($isSerial){$st=db()->prepare("SELECT serial_barcode FROM product_serials WHERE batch_id=? AND status='AVAILABLE' ORDER BY id");$st->execute([$id]);$serials=array_column($st->fetchAll(),'serial_barcode');$requested=max(0,(int)($_GET['count']??count($serials)));$count=min(500,count($serials),$requested?:count($serials));$serials=array_slice($serials,0,$count);}else{$count=max(1,min(500,(int)($_GET['count']??ceil($b['qty_received']))));}page_header('Print Barcode Labels');?>
<?php if($isSerial&&!$serials):?><div class="notice">No AVAILABLE unique-piece barcodes remain in this batch. Sold/damaged/returned labels are not reprinted.</div><?php endif;?><div class="no-print actions"><form method="get"><input type="hidden" name="batch_id" value="<?=$id?>"><label>Labels</label><input type="number" name="count" value="<?=$count?>" min="1" max="500" style="width:100px"><button class="btn">Refresh</button></form><button class="btn" onclick="print()">Print</button></div><br><div id="labels" class="labels"></div>
<style>.labels{display:grid;grid-template-columns:repeat(auto-fill,minmax(260px,1fr));gap:10px}.label{border:1px solid #aaa;padding:10px;text-align:center;break-inside:avoid}.label .name{font-weight:800}.label svg{max-width:100%;height:62px}@media print{.labels{grid-template-columns:repeat(3,1fr);gap:4px}.label{font-size:10px;padding:5px}}</style>
<script src="assets/js/qrcode.js"></script><script src="assets/js/label_qr.js"></script>
<script>
const patterns=['212222','222122','222221','121223','121322','131222','122213','122312','132212','221213','221312','231212','112232','122132','122231','113222','123122','123221','223211','221132','221231','213212','223112','312131','311222','321122','321221','312212','322112','322211','212123','212321','232121','111323','131123','131321','112313','132113','132311','211313','231113','231311','112133','112331','132131','113123','113321','133121','313121','211331','231131','213113','213311','213131','311123','311321','331121','312113','312311','332111','314111','221411','431111','111224','111422','121124','121421','141122','141221','112214','112412','122114','122411','142112','142211','241211','221114','413111','241112','134111','111242','121142','121241','114212','124112','124211','411212','421112','421211','212141','214121','412121','111143','111341','131141','114113','114311','411113','411311','113141','114131','311141','411131','211412','211214','211232','2331112'];
function code128Svg(text){let vals=[104],sum=104;for(let i=0;i<text.length;i++){let c=text.charCodeAt(i);if(c<32||c>126)c=63;let v=c-32;vals.push(v);sum+=v*(i+1);}vals.push(sum%103,106);let x=10,bars='';for(const v of vals){const p=patterns[v];for(let i=0;i<p.length;i++){const w=parseInt(p[i])*2;if(i%2===0)bars+=`<rect x="${x}" y="0" width="${w}" height="45"/>`;x+=w;}}return `<svg viewBox="0 0 ${x+10} 60" xmlns="http://www.w3.org/2000/svg">${bars}<text x="${(x+10)/2}" y="58" font-size="10" text-anchor="middle">${text.replace(/&/g,'&amp;').replace(/</g,'&lt;')}</text></svg>`;}
const data=<?=json_encode(['batch_barcode'=>$b['batch_barcode'],'serials'=>$serials,'name'=>$b['product_name'],'sku'=>$b['sku'],'variant'=>trim($b['color'].' '.$b['size']),'mrp'=>(float)$b['mrp'],'price'=>(float)$b['retail_price'],'count'=>$count,'is_serial'=>$isSerial],JSON_UNESCAPED_UNICODE|JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT)?>;
function esc(s){return String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
const priceLine=(data.price>0?'₹'+data.price.toFixed(2):'')+(data.mrp>data.price?' · MRP ₹'+data.mrp.toFixed(2):'');
let html='';for(let i=0;i<data.count;i++){let code=data.is_serial?data.serials[i]:data.batch_barcode;if(!code)break;html+=`<div class="label" data-code="${esc(code)}"><div class="name">PRATYANGI FASHIONS</div><div>${esc(data.name)}</div><div>${esc(data.sku)}${data.variant?' · '+esc(data.variant):''}</div>${code128Svg(code)}<div>${data.is_serial?'UNIQUE PIECE':'BATCH'}${priceLine?' · '+priceLine:''}</div></div>`;}document.getElementById('labels').innerHTML=html;if(window.PFLabelQR)PFLabelQR();
</script><?php page_footer();
